import numpy as np
from scipy.spatial.transform import Rotation as R
q=np.array([-1.571,1.571,0,1.376,0,1.485,1.308])
d=[.1575,.2025,.2045,.2155,.1845,.2155,.081]
axes=[[0,0,1],[0,1,0],[0,0,1],[0,-1,0],[0,0,1],[0,1,0],[0,0,1]]
for mode in range(3):
 T=np.eye(4); T[:3,3]=[0,.4,0]
 # offsets along current z before rotation
 for i in range(7):
  if mode==0: T[:3,3]+=T[:3,:3]@np.array([0,0,d[i]])
  if mode==1: T[:3,3]+=T[:3,:3]@np.array([0,0,d[i] if i==0 else 0])
  T[:3,:3]=T[:3,:3]@R.from_rotvec(np.array(axes[i])*q[i]).as_matrix()
  if mode==1 and i>0:T[:3,3]+=T[:3,:3]@np.array([0,0,d[i]])
 print(mode,T[:3,3],T[:3,2],T[:3,0],T[:3,1])
